<style>
	.rx-list{--rx-list-py:14px;--rx-list-px:16px;--rx-list-radius:12px;position:relative;isolation:isolate;display:grid;list-style:none;margin:0;padding:0;gap:0;width:100%;overflow:hidden;border:1px solid rgb(var(--rx-border));border-radius:var(--rx-list-radius);background:rgb(var(--rx-surface-2))}.rx-list.is-plain{border:0;border-radius:0;background:transparent}.rx-list.is-disabled{opacity:.6;pointer-events:none}.rx-list[data-size=sm]{--rx-list-py:10px;--rx-list-px:12px}.rx-list[data-size=lg]{--rx-list-py:18px;--rx-list-px:20px}.rx-list[data-radius=none]{--rx-list-radius:0}.rx-list[data-radius=subtle]{--rx-list-radius:8px}.rx-list[data-radius=pill]{--rx-list-radius:26px}.rx-list[data-radius=squircle]{--rx-list-radius:22px}.rx-list li{position:relative;z-index:1;min-width:0;max-height:140px;overflow:hidden;transition:max-height 280ms cubic-bezier(.22,1,.36,1),opacity 220ms}.rx-list li.is-removing{max-height:0;opacity:0}.rx-list li+li{border-top:1px solid rgb(var(--rx-border))}.rx-list__control{position:relative;isolation:isolate;z-index:2;display:flex;width:100%;box-sizing:border-box;align-items:center;gap:12px;padding:var(--rx-list-py) var(--rx-list-px);border:0;background:rgb(var(--rx-surface-2));color:rgb(var(--rx-text));text-align:left;text-decoration:none;font:inherit;cursor:grab;outline:0;touch-action:pan-y;user-select:none;transition:background 200ms,transform 460ms cubic-bezier(.34,1.85,.4,1),box-shadow 260ms,opacity 200ms,border-color 200ms}.rx-list__control:active{cursor:grabbing}.rx-list__control:focus-visible{box-shadow:inset 0 0 0 2px rgb(var(--rx-color))}.rx-list__control:hover{background:rgb(var(--rx-surface-3))}.rx-list [aria-selected=true]{background:color-mix(in srgb,rgb(var(--rx-color)) 14%,rgb(var(--rx-surface-2)))}.rx-list li.is-active .rx-list__control{box-shadow:inset 3px 0 rgb(var(--rx-color))}.rx-list__actions{position:absolute;inset-block:0;z-index:1;display:flex;overflow:hidden;transition:width 460ms cubic-bezier(.34,1.85,.4,1)}.rx-list__acti